87:   const omittedSockets: string[] = [];
88:   const omittedRuntimeCredentials: string[] = [];
89:   async function walk(directory: string, prefix = ""): Promise<void> {
90:     for (const entry of (await readdir(directory)).sort()) {
91:       const name = prefix + entry,
92:         path = join(directory, entry);
93:       const stat = await lstat(path);
94:       assert.ok(!stat.isSymbolicLink(), `State symlink refused: ${name}`);
95:       if (runtimeCredentialDirectory(name)) {
96:         assert.ok(
97:           stat.isDirectory() && allowRuntimeCredentials,
98:           "Runtime credentials must not be restored from backup",
99:         );
100:         omittedRuntimeCredentials.push(name);
101:         continue;
102:       }
103:       if (stat.isDirectory()) await walk(path, `${name}/`);
104:       else if (stat.isSocket()) omittedSockets.push(name);
105:       else {
106:         assert.ok(stat.isFile(), `Unsupported state entry: ${name}`);
107:         if (!/\.db(?:-wal|-shm|-journal)?$/.test(name))
108:           files[name] = await hashFile(path);
109:       }
110:     }
111:   }
112:   await walk(root);
113:   return {
114:     files,
115:     omittedSockets,
116:     ...(omittedRuntimeCredentials.length ? { omittedRuntimeCredentials } : {}),
117:   };
118: }
