120: async function databaseInventory(root: string): Promise<string[]> {
121:   const databases: string[] = [];
122:   async function walk(directory: string, prefix = ""): Promise<void> {
123:     for (const entry of (await readdir(directory)).sort()) {
124:       const name = prefix + entry,
125:         path = join(directory, entry);
126:       const stat = await lstat(path);
