128:       if (runtimeCredentialDirectory(name) && stat.isDirectory()) continue;
129:       if (stat.isDirectory()) await walk(path, `${name}/`);
130:       else if (stat.isSocket() || /\.db-(?:wal|shm|journal)$/.test(name)) {
