152:   assert.ok(
153:     !(await lstat(state)).isSymbolicLink(),
154:     "State root symlink refused",
155:   );
156:   await mkdir(target, { mode: 0o700 }); // Exclusive: never reuse/overwrite a backup.
157:   const before = await fileInventory(state);
158:   const receipt: BackupReceipt = {
159:     databaseHashes: {},
160:     databases: [],
161:     ...before,
162:   };
163:   async function walk(directory: string, prefix = ""): Promise<void> {
164:     for (const entry of (await readdir(directory)).sort()) {
165:       const name = prefix + entry,
166:         source = join(directory, entry),
167:         dest = join(target, name);
168:       const stat = await lstat(source);
169:       assert.ok(!stat.isSymbolicLink(), `State symlink refused: ${name}`);
170:       if (runtimeCredentialDirectory(name) && stat.isDirectory()) continue;
171:       if (stat.isDirectory()) {
172:         await mkdir(dest, { mode: 0o700 });
173:         await walk(source, `${name}/`);
174:         await sync(dest);
175:       } else if (stat.isSocket() || /\.db-(?:wal|shm|journal)$/.test(name)) {
176:         // Process endpoints and online SQLite sidecars are never restored.
177:       } else if (name.endsWith(".db")) {
178:         const db = new DatabaseSync(source, { readOnly: true });
179:         try {
180:           await backup(db, dest);
181:         } finally {
182:           db.close();
183:         }
184:         await chmod(dest, 0o600);
185:         verifyDatabase(dest);
186:         receipt.databases.push(name);
187:         await sync(dest);
188:         receipt.databaseHashes[name] = await hashFile(dest);
189:       } else {
190:         assert.ok(stat.isFile(), `Unsupported state entry: ${name}`);
191:         await copyFile(source, dest, 1 /* COPYFILE_EXCL */);
192:         await chmod(dest, 0o600 | (stat.mode & 0o100));
193:         await sync(dest);
194:       }
195:     }
196:   }
197:   await walk(state);
198:   assert.deepEqual(
199:     await fileInventory(state),
200:     before,
201:     "State files changed during backup",
202:   );
203:   await verifyStateBackup(target, receipt);
204:   await sync(target);
205:   return receipt;
206: }
