208: function verifyDatabase(path: string): void {
209:   // A WAL-mode backup may need its own sidecars on first open. Verify writable
210:   // in the private backup directory, never immutable/read-only against live WAL.
211:   const db = new DatabaseSync(path);
212:   try {
213:     assert.deepEqual(
214:       db
215:         .prepare("PRAGMA quick_check")
216:         .all()
217:         .map((r) => Object.values(r)[0]),
218:       ["ok"],
219:     );
220:     assert.deepEqual(db.prepare("PRAGMA foreign_key_check").all(), []);
221:     db.exec("PRAGMA journal_mode=DELETE;");
222:   } finally {
223:     db.close();
224:   }
225: }
