227: export async function verifyStateBackup(
228:   target: string,
229:   receipt: BackupReceipt,
230: ): Promise<true> {
231:   const databases = await databaseInventory(target);
232:   assert.deepEqual(
233:     databases,
234:     [...receipt.databases].sort(),
235:     "Backup database set mismatch",
236:   );
237:   assert.deepEqual(
238:     Object.keys(receipt.databaseHashes ?? {}).sort(),
239:     databases,
240:     "Backup database digest set mismatch",
241:   );
242:   for (const name of databases) {
243:     const path = join(target, name);
244:     verifyDatabase(path);
245:     assert.equal(
246:       await hashFile(path),
247:       receipt.databaseHashes[name],
248:       `Backup database digest mismatch: ${name}`,
249:     );
250:   }
251:   assert.deepEqual(
252:     (await fileInventory(target, false)).files,
253:     receipt.files,
254:     "Backup file digest mismatch",
255:   );
256:   return true;
257: }

